         //     (a1 ≢ true AND a2 ≢ true AND a3 ≢ true AND a4 ≢ true AND a5 ≢ true AND a6 ≢ true)
         //
         // which can be further simplified to:
         //
         //     a1 ≢ true AND a2 ≢ true AND (a3 ≡ true OR (a4 ≢ true AND (a5 ≡ true OR a6 ≢ true)))
         //
