 private void advanceAndSchedule(IntList next, int threadId, int pointer, int inputIndex, Runtime runtime)
     {
         // avoid empty loop and try avoid exponential processing
         ArrayView threadsAtInstruction = runtime.threadsAtInstructions.getArrayView(pointer);
         for (int i = 0; i < threadsAtInstruction.length(); i++) {
             int thread = threadsAtInstruction.get(i);
             if (threadEquivalence.equivalent(
                     thread,
                     runtime.captures.getLabels(thread),
                     runtime.aggregations.get(thread),
                     threadId,
                     runtime.captures.getLabels(threadId),
                     runtime.aggregations.get(threadId),
                     pointer)) {
                 // in case of equivalent threads, kill the one that comes later, because it is on a less preferred path
                 runtime.scheduleKill(threadId);
                 return;
             }
         }
         runtime.threadsAtInstructions.add(pointer, threadId);

         Instruction instruction = program.at(pointer);
         switch (instruction.type()) {
             case MATCH_START -> {
                 if (inputIndex == 0 && runtime.matchingAtPartitionStart) {
                     advanceAndSchedule(next, threadId, pointer + 1, inputIndex, runtime);
                 }
                 else {
                     runtime.scheduleKill(threadId);
                 }
             }
             case MATCH_END -> {
                 if (inputIndex == runtime.inputLength) {
                     advanceAndSchedule(next, threadId, pointer + 1, inputIndex, runtime);
                 }
                 else {
                     runtime.scheduleKill(threadId);
                 }
             }
             case JUMP -> advanceAndSchedule(next, threadId, ((Jump) instruction).getTarget(), inputIndex, runtime);
             case SPLIT -> {
                 int forked = runtime.forkThread(threadId);
-                advanceAndSchedule(next, threadId, ((Split) instruction).getFirst(), inputIndex, runtime);
-                advanceAndSchedule(next, forked, ((Split) instruction).getSecond(), inputIndex, runtime);
+                advanceAndSchedule(next, threadId, ((Split) instruction).first(), inputIndex, runtime);
+                advanceAndSchedule(next, forked, ((Split) instruction).second(), inputIndex, runtime);
             }
             case SAVE -> {
                 runtime.captures.save(threadId, inputIndex);
                 advanceAndSchedule(next, threadId, pointer + 1, inputIndex, runtime);
             }
             default -> {
                 // MATCH_LABEL or DONE
                 runtime.threads.set(threadId, pointer);
                 next.add(threadId);
             }
         }
     }

 private static Set<Integer> reachableLabels(Program program, int instructionIndex, boolean[] visited)
     {
         if (visited[instructionIndex]) {
             return new HashSet<>();
         }

         visited[instructionIndex] = true;

         Set<Integer> reachableLabels = new HashSet<>();
         Instruction instruction = program.at(instructionIndex);
         switch (instruction.type()) {
             case MATCH_LABEL -> {
                 reachableLabels.addAll(reachableLabels(program, instructionIndex + 1, visited));
                 reachableLabels.add(((MatchLabel) instruction).getLabel());
             }
             case JUMP -> reachableLabels.addAll(reachableLabels(program, ((Jump) instruction).getTarget(), visited));
             case SPLIT -> {
-                reachableLabels.addAll(reachableLabels(program, ((Split) instruction).getFirst(), visited));
-                reachableLabels.addAll(reachableLabels(program, ((Split) instruction).getSecond(), visited));
+                reachableLabels.addAll(reachableLabels(program, ((Split) instruction).first(), visited));
+                reachableLabels.addAll(reachableLabels(program, ((Split) instruction).second(), visited));
             }
             case MATCH_START, MATCH_END, SAVE -> reachableLabels.addAll(reachableLabels(program, instructionIndex + 1, visited));
             case DONE -> {
                 // no reachable labels
             }
         }

         return reachableLabels;
     }

