 @Nullable
     private static NullIf matchIfFirstEqualsSecond(Expression expression)
     {
         if (!(expression instanceof Case caseExpression) || caseExpression.whenClauses().size() != 1) {
             return null;
         }
         WhenClause when = caseExpression.whenClauses().get(0);
-        if (!(matchComparison(when.getOperand()) instanceof Comparison.Equal(Expression left, Expression right))) {
+        if (!(matchComparison(when.operand()) instanceof Comparison.Equal(Expression left, Expression right))) {
             return null;
         }
-        if (!isConstantNull(when.getResult())) {
+        if (!isConstantNull(when.result())) {
             return null;
         }
         if (!caseExpression.defaultValue().equals(left)) {
             return null;
         }
         // The first operand occurs in both the condition and the default: collapsing the two
         // independent evaluations into the pattern's single occurrence is only sound when it is
         // deterministic.
         if (!isDeterministic(left)) {
             return null;
         }
         return new NullIf(left, right);
     }

 @Override
     public Optional<Expression> apply(Expression expression, Session session, SymbolAllocator symbolAllocator, Map<Symbol, Expression> bindings)
     {
         if (!(expression instanceof Case(List<WhenClause> whenClauses, Expression defaultValue))) {
             return Optional.empty();
         }

         List<WhenClause> newClauses = new ArrayList<>();
         Expression newDefault = defaultValue;

         Set<Expression> seen = new HashSet<>();
         boolean changed = false;
         for (WhenClause whenClause : whenClauses) {
-            if (seen.contains(whenClause.getOperand()) || whenClause.getOperand().equals(FALSE) || whenClause.getOperand().equals(NULL_BOOLEAN)) {
+            if (seen.contains(whenClause.operand()) || whenClause.operand().equals(FALSE) || whenClause.operand().equals(NULL_BOOLEAN)) {
                 changed = true;
             }
-            else if (whenClause.getOperand().equals(TRUE)) {
+            else if (whenClause.operand().equals(TRUE)) {
                 changed = true;
-                newDefault = whenClause.getResult();
+                newDefault = whenClause.result();
                 break;
             }
             else {
                 newClauses.add(whenClause);

-                if (isDeterministic(whenClause.getOperand())) {
-                    seen.add(whenClause.getOperand());
+                if (isDeterministic(whenClause.operand())) {
